import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.DncwoWA8.js";const n="/projects/ai-skills/diagrams/plan-a-project.svg",f=JSON.parse('{"title":"Plan a project or feature","description":"","frontmatter":{"title":"Plan a project or feature"},"headers":[],"relativePath":"workflows/plan-a-project.md","filePath":"workflows/plan-a-project.md"}'),r={name:"workflows/plan-a-project.md"};function o(l,e,c,p,d,h){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="plan-a-project-or-feature" tabindex="-1">Plan a project or feature <a class="header-anchor" href="#plan-a-project-or-feature" aria-label="Permalink to &quot;Plan a project or feature&quot;">​</a></h1><p>Define what a project or feature must achieve, which limitations it must respect, and which tasks an implementer can start.</p><p>Start with an idea, a problem, or partly agreed requirements. Finish with agreed scope and verifiable tasks. You can also stop at research findings, a brief, or a specification when that is the requested result.</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p><img src="'+n+`" alt="Planning entry points, skill handoffs, and returns to scope or behavior agreement."></p><p><a href="/projects/ai-skills/diagrams/plan-a-project.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/plan-a-project.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/plan-a-project.json">Editable source</a></p><p>The diagram shows suggested handoffs, not automatic execution or new instruction dependencies. Select a node in the interactive diagram for its source references.</p><details><summary>Read the flow as text</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>/research</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>/initiative</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>/specify</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>/plan-tasks</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Stop with the next ready task</span></span></code></pre></div></details><p>Enter at the first unresolved stage. If the direction is already agreed, start at <code>specify</code>. If the scope is already sufficient, start at <code>plan-tasks</code>. Return to research when a missing fact blocks a decision, or to the initiative when proposed behavior changes the agreed scope.</p><h2 id="choose-your-entry-point" tabindex="-1">Choose your entry point <a class="header-anchor" href="#choose-your-entry-point" aria-label="Permalink to &quot;Choose your entry point&quot;">​</a></h2><p>Use a trusted project and read its instructions. Check the <a href="/projects/ai-skills/workflows/supporting-tools.html#before-you-start">installed skills and their requirements</a>. Agree whether findings belong in chat, project files, or a tracker before writing them.</p><ul><li>Start with <a href="/projects/ai-skills/skills/research.html"><code>research</code></a> when facts or feasibility are missing. Carry forward evidence, alternatives, uncertainties, and source limits.</li><li>Start with <a href="/projects/ai-skills/skills/initiative.html"><code>initiative</code></a> when the problem, outcomes, or limitations need agreement. Carry forward a brief with scope and success measures.</li><li>Start with <a href="/projects/ai-skills/skills/specify.html"><code>specify</code></a> when observable behavior is unsettled. Carry forward requirements and agreed test boundaries.</li><li>Start with <a href="/projects/ai-skills/skills/plan-tasks.html"><code>plan-tasks</code></a> when agreed work needs dividing. Carry forward bounded tasks, dependencies, and completion evidence.</li></ul><p>A separate document for every stage is unnecessary. Existing confirmed decisions count. Research can answer a question without producing any implementation work.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-investigate-facts-that-could-change-the-plan" tabindex="-1">1. Investigate facts that could change the plan <a class="header-anchor" href="#_1-investigate-facts-that-could-change-the-plan" aria-label="Permalink to &quot;1. Investigate facts that could change the plan&quot;">​</a></h3><p>Use <code>research</code> to inspect supplied references and relevant project evidence. Compare alternatives where useful. Ask the user for decisions, not facts available in the project.</p><p>The result should separate findings, assumptions, recommendations, and unknowns. Do not pass a recommendation to the next stage as though the user has accepted it.</p><h3 id="_2-agree-on-outcomes-and-limitations" tabindex="-1">2. Agree on outcomes and limitations <a class="header-anchor" href="#_2-agree-on-outcomes-and-limitations" aria-label="Permalink to &quot;2. Agree on outcomes and limitations&quot;">​</a></h3><p>Use <code>initiative</code> to settle the problem, affected people, desired outcomes, scope, exclusions, and success or failure measures.</p><p>Record relevant limitations explicitly. These may include compatibility, security, performance, operating conditions, budget, or deployment restrictions. Resolve their actual values with the owner. Do not invent targets to complete a template.</p><p>Continue when the owner confirms the brief. If this agreement already exists, reuse it.</p><h3 id="_3-define-observable-correctness" tabindex="-1">3. Define observable correctness <a class="header-anchor" href="#_3-define-observable-correctness" aria-label="Permalink to &quot;3. Define observable correctness&quot;">​</a></h3><p>Use <code>specify</code> to turn confirmed decisions into behavior that an implementer and reviewer can check. Give acceptance criteria stable identifiers. Include failures, boundaries, exact agreed values, and the interfaces where tests will observe behavior.</p><p>Resolve conflicting requirements before drafting around them. Return to the brief when a new decision would change its scope.</p><h3 id="_4-divide-the-work-into-reviewable-tasks" tabindex="-1">4. Divide the work into reviewable tasks <a class="header-anchor" href="#_4-divide-the-work-into-reviewable-tasks" aria-label="Permalink to &quot;4. Divide the work into reviewable tasks&quot;">​</a></h3><p>Use <code>plan-tasks</code> to create deliverables that can be completed and verified without repeating the design discussion. Prefer working end-to-end slices where practical.</p><p>For each task, state its boundary, covered requirements, completion evidence, dependencies, and results needed by later tasks. Keep necessary tests and documentation with the deliverable. Use inspected project paths and commands rather than guessed ones.</p><p>Check that all in-scope requirements are covered and dependencies have no cycles. Name the next ready task.</p><h2 id="use-clarification-where-it-helps" tabindex="-1">Use clarification where it helps <a class="header-anchor" href="#use-clarification-where-it-helps" aria-label="Permalink to &quot;Use clarification where it helps&quot;">​</a></h2><p>An interview is useful when decisions remain open, not as a separate stage that must be repeated after each skill.</p><div class="warning custom-block"><p class="custom-block-title">Current instruction requirements</p><p>The current <code>research</code>, <code>initiative</code>, and <code>specify</code> skills declare <code>grilling</code> as required instructions. Load those requirements even when an interview is unnecessary. The intended contextual use of interviews does not make the declared dependency optional. This guide does not change skill metadata.</p></div><p>See <a href="/projects/ai-skills/workflows/supporting-tools.html#clarification-and-explanation">supporting clarification tools</a> for focused questioning or a clearer explanation.</p><h2 id="example-plan-filtered-csv-export" tabindex="-1">Example: plan filtered CSV export <a class="header-anchor" href="#example-plan-filtered-csv-export" aria-label="Permalink to &quot;Example: plan filtered CSV export&quot;">​</a></h2><p>This is an illustrative project, not a feature implemented by this collection.</p><p>A reporting application needs CSV export. The owner has not agreed which rows, columns, limits, or failure cases belong in the feature. After loading the relevant installed skills, send a request such as:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>Plan CSV export for the current filtered report. Inspect the project first.</span></span>
<span class="line"><span>Use /research only for facts that could change the approach. Agree the</span></span>
<span class="line"><span>outcome and limitations, /specify observable behavior, and divide the scope</span></span>
<span class="line"><span>into verifiable tasks. Keep the result in chat for review. Do not implement.</span></span></code></pre></div><p>The expected handoff contains:</p><ul><li>A brief explaining who needs export, which report it covers, and what is excluded.</li><li>Acceptance criteria for selected rows, columns, quoting, encoding, limits, permissions, and failures, with values agreed by the owner.</li><li>Tasks that identify the behavior they deliver, how to verify it, and any genuine blockers.</li></ul><p>If the existing export contract already settles these questions, skip the interview and reuse that contract. If an unknown limit prevents agreement, stop with that question rather than produce implementation-ready tasks.</p><h2 id="hand-off-and-stop" tabindex="-1">Hand off and stop <a class="header-anchor" href="#hand-off-and-stop" aria-label="Permalink to &quot;Hand off and stop&quot;">​</a></h2><p>Report the agreed records, their actual location, remaining uncertainty, requirement coverage, and next ready task. A plan is not permission to start coding or delegate it.</p><p>When the owner selects a task for execution, continue with <a href="/projects/ai-skills/workflows/implement-a-task.html">Implement a planned task</a>.</p><p>For a narrower procedure, see <a href="/projects/ai-skills/workflows/research-a-decision.html">research</a>, <a href="/projects/ai-skills/workflows/shape-an-initiative.html">initiative</a>, <a href="/projects/ai-skills/workflows/specify-observable-behavior.html">specification</a>, or <a href="/projects/ai-skills/workflows/plan-bounded-tasks.html">task breakdown</a>.</p>`,43)])])}const m=a(r,[["render",o]]);export{f as __pageData,m as default};
